// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mockStatic;

import java.nio.file.Path;
import java.util.Arrays;

import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.csf.PersistentCsfPageCodec;
import org.eclipse.rdf4j.sail.lmdb.csf.PersistentCsfPageCodec.DecodedPage;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.api.parallel.Isolated;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.EnumSource;
import org.lwjgl.util.lmdb.LMDB;
import org.mockito.MockedStatic;

/** Planning estimates must not turn a residual constraint into an unbounded statement scan. */
@Isolated
class LmdbPersistentCardinalityWorkTest {

	private static final long PREDICATE = 42;
	private static final long OBJECT = 900_000;
	private static final long MATCHING_CONTEXT = 7;
	private static final int SMALL_ROWS_PER_PLANE = 8 * LmdbPersistentAdjacency.PAGE_QUADS;
	// Permit three sampled pages and both range-fence pages per plane, rather than demanding old numeric estimates.
	private static final int MAX_PAGE_WALKS = 2 * (Statistics.MAX_BUCKETS + 2);
	private static final long MAX_NATIVE_READS = 4_096;

	@TempDir
	Path directory;

	@ParameterizedTest
	@EnumSource(EstimatorMode.class)
	@Timeout(120)
	void residualEstimateWorkIsBoundedAsBothPlanesDouble(EstimatorMode mode) throws Exception {
		String previous = System.getProperty(TripleStore.DISABLE_PAGE_WALKING_ESTIMATOR_PROPERTY);
		System.setProperty(TripleStore.DISABLE_PAGE_WALKING_ESTIMATOR_PROPERTY,
				Boolean.toString(mode.disableProperty));
		try {
			LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
					.setPageCardinalityEstimator(mode.configured)
					.setSketchEstimatorEnabled(false)
					.setTripleDBSize(64L << 20);
			try (TripleStore store = new TripleStore(directory.toFile(), config, null)) {
				appendRows(store, 0, SMALL_ROWS_PER_PLANE);
				assertExactMetadataCounts(store, SMALL_ROWS_PER_PLANE);
				Observation small = residualEstimate(store);
				appendRows(store, SMALL_ROWS_PER_PLANE, SMALL_ROWS_PER_PLANE);
				assertExactMetadataCounts(store, 2 * SMALL_ROWS_PER_PLANE);
				Observation large = residualEstimate(store);
				System.out.printf(
						"persistent-cardinality mode=%s rowsPerPlane=%d small=%s largeRowsPerPlane=%d large=%s%n",
						mode, SMALL_ROWS_PER_PLANE, small, 2 * SMALL_ROWS_PER_PLANE, large);
				assertBounded(small, SMALL_ROWS_PER_PLANE);
				assertBounded(large, 2 * SMALL_ROWS_PER_PLANE);
			}
		} finally {
			if (previous == null) {
				System.clearProperty(TripleStore.DISABLE_PAGE_WALKING_ESTIMATOR_PROPERTY);
			} else {
				System.setProperty(TripleStore.DISABLE_PAGE_WALKING_ESTIMATOR_PROPERTY, previous);
			}
		}
	}

	private static void appendRows(TripleStore store, int start, int count) throws Exception {
		long[] subjects = new long[count];
		long[] predicates = new long[count];
		long[] objects = new long[count];
		long[] contexts = new long[count];
		Arrays.fill(predicates, PREDICATE);
		Arrays.fill(objects, OBJECT);
		store.startTransaction();
		for (boolean explicit : new boolean[] { true, false }) {
			for (int row = 0; row < count; row++) {
				// Disjoint subjects prevent explicit promotion from removing the inferred control plane.
				subjects[row] = (explicit ? 10_000L : 100_000L) + start + row;
				contexts[row] = (start + row) % 2 == 0 ? MATCHING_CONTEXT : MATCHING_CONTEXT + 1;
			}
			store.storeTriplesAligned(subjects, predicates, objects, contexts, count, explicit);
		}
		// The work oracle must count decompression, not merely the few native seeks to packed page values.
		LmdbPersistentAdjacency.openExisting(store.writeTxn).compact(store.writeTxn, true);
		store.commit();
	}

	private static void assertExactMetadataCounts(TripleStore store, int rowsPerPlane) throws Exception {
		try (NativeWork work = new NativeWork()) {
			assertThat(store.cardinality(-1, -1, -1, -1)).isEqualTo(2D * rowsPerPlane);
			assertThat(store.cardinality(-1, PREDICATE, -1, -1)).isEqualTo(2D * rowsPerPlane);
			assertThat(store.cardinality(-1, -1, -1, MATCHING_CONTEXT)).isEqualTo((double) rowsPerPlane);
			assertThat(work.pointReads).as("actual persisted count keys, in all estimator modes").isPositive();
			assertThat(work.cursorReads).as("exact metadata counts do not enumerate statements").isZero();
			assertThat(work.decodedPages + work.probedPages).isZero();
		}
	}

	private static Observation residualEstimate(TripleStore store) throws Exception {
		try (NativeWork work = new NativeWork()) {
			double estimate = store.cardinality(-1, PREDICATE, -1, MATCHING_CONTEXT);
			return new Observation(estimate, work.pointReads, work.cursorReads, work.decodedPages,
					work.decodedRows, work.probedPages);
		}
	}

	private static void assertBounded(Observation observation, int rowsPerPlane) {
		assertThat(observation.estimate()).isFinite().isBetween(0D, 2D * rowsPerPlane);
		assertThat(observation.pointReads() + observation.cursorReads())
				.as("snapshot-local native work must be real and bounded: %s", observation)
				.isPositive()
				.isLessThanOrEqualTo(MAX_NATIVE_READS);
		assertThat(observation.decodedPages() + observation.probedPages())
				.as("packing many rows into a page must not hide exhaustive planning work: %s", observation)
				.isLessThanOrEqualTo(MAX_PAGE_WALKS);
		assertThat(observation.decodedRows())
				.as("decode work is bounded independently of the population: %s", observation)
				.isLessThanOrEqualTo((long) MAX_PAGE_WALKS * PersistentCsfPageCodec.MAX_PAIRS);
	}

	private enum EstimatorMode {
		ENABLED(true, false),
		DISABLED_BY_CONFIG(false, false),
		DISABLED_BY_PROPERTY(true, true);

		private final boolean configured;
		private final boolean disableProperty;

		EstimatorMode(boolean configured, boolean disableProperty) {
			this.configured = configured;
			this.disableProperty = disableProperty;
		}
	}

	private record Observation(double estimate, long pointReads, long cursorReads, long decodedPages,
			long decodedRows, long probedPages) {
	}

	/** Observes real calls on the test thread; no native result, page, or iterator is substituted. */
	private static final class NativeWork implements AutoCloseable {
		private final MockedStatic<LMDB> nativeCalls;
		private final MockedStatic<PersistentCsfPageCodec> codecCalls;
		private int nativeDepth;
		private long pointReads;
		private long cursorReads;
		private long decodedPages;
		private long decodedRows;
		private long probedPages;

		NativeWork() {
			nativeCalls = mockStatic(LMDB.class, invocation -> {
				boolean outermost = nativeDepth++ == 0;
				try {
					if (outermost) {
						String method = invocation.getMethod().getName();
						if (method.equals("mdb_get")) {
							pointReads++;
						} else if (method.equals("mdb_cursor_get")) {
							cursorReads++;
						}
					}
					return invocation.callRealMethod();
				} finally {
					nativeDepth--;
				}
			});
			try {
				codecCalls = mockStatic(PersistentCsfPageCodec.class, invocation -> {
					Object result = invocation.callRealMethod();
					if (invocation.getMethod().getName().equals("decode")) {
						decodedPages++;
						decodedRows += ((DecodedPage) result).size();
					} else if (invocation.getMethod().getName().equals("probe")) {
						probedPages++;
					}
					return result;
				});
			} catch (RuntimeException | Error failure) {
				nativeCalls.close();
				throw failure;
			}
		}

		@Override
		public void close() {
			try {
				codecCalls.close();
			} finally {
				nativeCalls.close();
			}
		}
	}
}
